const CHAPTERS = [{"id": 1, "title": "Problem solving and logical thinking", "hint": "Separate symptoms from causes. A process needs evidence and evaluation, not merely completion of its steps.", "questions": [{"id": "m1-1", "number": 1, "text": "Which tool organizes potential causes of a problem into branches?", "options": ["Fishbone diagram", "HTML form", "Class constructor", "CSS selector"], "answer": 0, "why": "A fishbone diagram groups possible causes to support root cause analysis."}, {"id": "m1-2", "number": 2, "text": "Root cause analysis focuses on why a problem occurs rather than only its symptoms.", "options": ["True", "False"], "answer": 0, "why": "Treating a symptom does not necessarily remove the underlying cause."}, {"id": "m1-3", "number": 3, "text": "Following a problem-solving process guarantees that the solution will succeed.", "options": ["True", "False"], "answer": 1, "why": "The proposed solution still needs testing and evaluation."}, {"id": "m1-4", "number": 4, "text": "A project keeps gaining unplanned features after work begins. What is this called?", "options": ["Scope creep", "Type conversion", "Encapsulation", "Compilation"], "answer": 0, "why": "Uncontrolled expansion of requirements can change cost and schedule."}, {"id": "m1-5", "number": 5, "text": "What should usually happen before implementing a solution?", "options": ["Understand the problem and requirements", "Write all the code immediately", "Buy the fastest server", "Skip evaluation"], "answer": 0, "why": "A clear problem definition helps avoid solving the wrong problem."}, {"id": "m1-6", "number": 6, "text": "Which could cause a project to fail?", "options": ["Unclear requirements", "Cost overruns", "Unsuitable technology", "All of these"], "answer": 3, "why": "Each issue can prevent an otherwise promising project from delivering its intended result."}], "source": "Assessment-based practice", "written": [{"id": "1-1", "number": 1, "text": "A registration website is slow. A team immediately purchases a larger server. What important problem-solving work might they have skipped?"}, {"id": "1-2", "number": 2, "text": "Which tool best organizes possible causes into branches: a fishbone diagram, a CSS stylesheet, or a class constructor? Explain its purpose."}, {"id": "1-3", "number": 3, "text": "True or false: completing a standard problem-solving process guarantees that the proposed solution works. Explain how you would verify success."}, {"id": "1-4", "number": 4, "text": "A client keeps requesting features after development begins. What project risk does this illustrate? How could it affect time and cost?"}, {"id": "1-5", "number": 5, "text": "Give one example each of an unclear requirement, solving the wrong problem, and choosing unsuitable technology."}]}, {"id": 2, "title": "HTML and CSS", "hint": "Ask whether a rule lives on one element, in one document, or in a reusable file.", "questions": [{"id": "m2-1", "number": 1, "text": "Which technology primarily defines the structure of a web page?", "options": ["HTML", "CSS", "PostgreSQL", "npm"], "answer": 0, "why": "HTML describes page structure; CSS handles presentation."}, {"id": "m2-2", "number": 2, "text": "HTML is primarily used to define program logic and calculations.", "options": ["True", "False"], "answer": 1, "why": "JavaScript commonly provides the behavior and calculations."}, {"id": "m2-3", "number": 3, "text": "A browser interprets HTML to display a web page.", "options": ["True", "False"], "answer": 0, "why": "The browser constructs and renders a page from markup and other resources."}, {"id": "m2-4", "number": 4, "text": "Which is the usual extension for a basic HTML document?", "options": [".js", ".html", ".css", ".sql"], "answer": 1, "why": "An HTML document is commonly stored with the .html extension."}, {"id": "m2-5", "number": 5, "text": "Which correctly writes an HTML comment?", "options": ["<!-- Study notes -->", "// Study notes", "<comment>Study notes</comment>", "/* Study notes */"], "answer": 0, "why": "HTML comments use an opening <!-- and closing -->."}, {"id": "m2-6", "number": 6, "text": "A paragraph has style=\"color: green\". Which CSS approach is used?", "options": ["External", "Internal", "Inline", "Server-side"], "answer": 2, "why": "Inline CSS appears in the element’s style attribute."}, {"id": "m2-7", "number": 7, "text": "CSS placed in a style element in the document head is called:", "options": ["Internal", "External", "Inline", "SQL"], "answer": 0, "why": "Internal styles belong to the HTML document itself."}, {"id": "m2-8", "number": 8, "text": "A stylesheet linked from a separate .css file is:", "options": ["Inline", "External", "Internal", "A script"], "answer": 1, "why": "An external stylesheet can be shared by multiple pages."}, {"id": "m2-9", "number": 9, "text": "Bootstrap provides reusable frontend styles and components.", "options": ["True", "False"], "answer": 0, "why": "Bootstrap is a frontend toolkit rather than a browser or a new programming language."}], "source": "Assessment-based practice", "written": [{"id": "2-1", "number": 1, "text": "A page needs a heading, blue text, and a calculation when a button is clicked. Assign each responsibility to HTML, CSS, or JavaScript."}, {"id": "2-2", "number": 2, "text": "True or false: the browser displays an HTML file by interpreting its markup. What role does the .html extension play?"}, {"id": "2-3", "number": 3, "text": "Write an HTML comment containing your name and a short description of a webpage."}, {"id": "2-4", "number": 4, "text": "Classify these as inline, internal, or external CSS: a style attribute on a paragraph; a style element in the head; a linked .css file."}, {"id": "2-5", "number": 5, "text": "Ten pages share the same appearance. Which CSS approach would make a site-wide font change easiest, and why?"}, {"id": "2-6", "number": 6, "text": "One paragraph uses an inline style. Would changing an unrelated paragraph's inline style automatically change it too?"}, {"id": "2-7", "number": 7, "text": "What does a frontend library such as Bootstrap provide? How does it differ from a browser or a programming language?"}]}, {"id": 3, "title": "Introduction to JavaScript", "hint": "Distinguish variable naming from variable types, and distinguish the engine's execution strategy from the language's syntax.", "questions": [{"id": "m3-1", "number": 1, "text": "JavaScript requires you to declare a fixed data type for each variable.", "options": ["True", "False"], "answer": 1, "why": "JavaScript is dynamically typed; the value determines its type."}, {"id": "m3-2", "number": 2, "text": "JIT compilation can optimize frequently executed JavaScript while the program runs.", "options": ["True", "False"], "answer": 0, "why": "JavaScript engines can compile and optimize code during execution."}, {"id": "m3-3", "number": 3, "text": "In a typical web interaction, which is the client?", "options": ["The user’s browser", "The database server", "The computer hosting the website", "The network cable"], "answer": 0, "why": "The browser requests resources from a server."}, {"id": "m3-4", "number": 4, "text": "What does a web framework primarily provide?", "options": ["Tools and conventions for developing web applications", "A replacement for all internet connections", "The browser’s address bar", "A database record"], "answer": 0, "why": "Frameworks support development with reusable structure and functionality."}, {"id": "m3-5", "number": 5, "text": "Which can browser developer tools help inspect?", "options": ["Console errors", "Page elements", "Network requests", "All of these"], "answer": 3, "why": "Developer tools expose multiple useful debugging views."}, {"id": "m3-6", "number": 6, "text": "The names alert and Alert refer to the same built-in JavaScript function.", "options": ["True", "False"], "answer": 1, "why": "JavaScript identifiers are case-sensitive."}, {"id": "m3-7", "number": 7, "text": "Semicolons can explicitly mark the ends of JavaScript statements.", "options": ["True", "False"], "answer": 0, "why": "JavaScript also has automatic semicolon insertion, so omission does not always cause an error."}], "source": "Assessment-based practice", "written": [{"id": "3-1", "number": 1, "text": "True or false: every JavaScript variable must have its data type declared before use."}, {"id": "3-2", "number": 2, "text": "Explain why a JavaScript engine might compile frequently executed code while a program runs. What does JIT mean?"}, {"id": "3-3", "number": 3, "text": "A browser requests a page from a remote computer. Identify the client and the server."}, {"id": "3-4", "number": 4, "text": "Describe how a web framework helps a developer. Is the framework the same thing as the website's browser?"}, {"id": "3-5", "number": 5, "text": "You click a button and nothing happens. Name three useful things to inspect in browser developer tools."}, {"id": "3-6", "number": 6, "text": "Would alert('Ready') and Alert('Ready') necessarily call the same function? Explain."}, {"id": "3-7", "number": 7, "text": "What purpose does a semicolon serve in JavaScript? Explain why omitting one is not the same as guaranteeing an error on every line."}]}, {"id": 4, "title": "Documentation, variables and data types", "hint": "Names communicate intent to people. They do not enforce JavaScript types.", "questions": [{"id": "m4-1", "number": 1, "text": "Documentation is best ignored until after a product is released.", "options": ["True", "False"], "answer": 1, "why": "Documentation during development helps explain intent and supports maintenance."}, {"id": "m4-2", "number": 2, "text": "Which starts a single-line JavaScript comment?", "options": ["//", "<!--", "<comment>", "**"], "answer": 0, "why": "Double forward slashes introduce a single-line comment."}, {"id": "m4-3", "number": 3, "text": "Which can enclose a multiline JavaScript comment?", "options": ["/* ... */", "<!-- ... -->", "// ... //", "<note> ... </note>"], "answer": 0, "why": "Slash-asterisk opens it and asterisk-slash closes it."}, {"id": "m4-4", "number": 4, "text": "Which type best represents whether a student has opted in to reminders?", "options": ["Boolean", "String", "Number", "BigInt"], "answer": 0, "why": "A boolean represents a true/false state."}, {"id": "m4-5", "number": 5, "text": "Which type normally represents a customer’s name?", "options": ["String", "Number", "Boolean", "BigInt"], "answer": 0, "why": "Text values are strings."}, {"id": "m4-6", "number": 6, "text": "Which type normally represents a price such as 24.95 in JavaScript?", "options": ["Number", "Boolean", "Date", "BigInt"], "answer": 0, "why": "Number represents both whole and fractional numeric values."}, {"id": "m4-7", "number": 7, "text": "What value does this variable initially hold?\n```js\nlet sCity;\n```", "options": ["undefined", "null", "An empty string", "0"], "answer": 0, "why": "A declaration without initialization gives the variable the value undefined."}, {"id": "m4-8", "number": 8, "text": "Hungarian notation in a variable name enforces its data type.", "options": ["True", "False"], "answer": 1, "why": "The prefix documents intent for people; JavaScript does not enforce it."}, {"id": "m4-9", "number": 9, "text": "Which JavaScript type is intended for integers beyond Number’s safe integer range?", "options": ["BigInt", "Boolean", "String only", "Float64 keyword"], "answer": 0, "why": "BigInt represents integers with arbitrary precision subject to resource limits."}], "source": "Assessment-based practice", "written": [{"id": "4-1", "number": 1, "text": "Why might writing documentation only after release make a program harder to maintain?"}, {"id": "4-2", "number": 2, "text": "Write one single-line JavaScript comment and one multiline comment. How do these differ from HTML comments?"}, {"id": "4-3", "number": 3, "text": "Choose a suitable JavaScript data type for each: a customer name, a price, permission to receive texts, and an integer beyond Number's safe integer range."}, {"id": "4-4", "number": 4, "text": "What is the value of `let sNickname;` immediately after declaration?"}, {"id": "4-5", "number": 5, "text": "Contrast a variable explicitly assigned null with one declared without an initializer."}, {"id": "4-6", "number": 6, "text": "Predict the type after each assignment: `let item = 12; item = 'twelve'; item = false;`."}, {"id": "4-7", "number": 7, "text": "Under your course's Hungarian naming convention, what would sCity, iCount, fRate, bActive, and dStart suggest?"}, {"id": "4-8", "number": 8, "text": "True or false: naming a variable iCount forces JavaScript to reject decimals stored in it."}, {"id": "4-9", "number": 9, "text": "Convert an unclear variable name such as x into a descriptive camelCase name for a client's workout total."}]}, {"id": 5, "title": "Input and output", "hint": "Parsing converts a value; formatting controls its displayed representation. Follow addition/concatenation from left to right.", "questions": [{"id": "m5-1", "number": 1, "text": "Where can JavaScript be included for an HTML page?", "options": ["In the head", "In the body", "In a linked script file", "All of these"], "answer": 3, "why": "Script elements can appear in different positions or reference external files."}, {"id": "m5-2", "number": 2, "text": "A user types 9.25 into prompt(). Before conversion, its return value is:", "options": ["A string", "A number", "A boolean", "A BigInt"], "answer": 0, "why": "For entered text, prompt returns a string. Cancel returns null."}, {"id": "m5-3", "number": 3, "text": "What is displayed?\n```js\nalert(parseInt(\"9.25\"));\n```", "options": ["9", "9.25", "9.3", "10"], "answer": 0, "why": "parseInt reads the integer portion; it is not ordinary rounding."}, {"id": "m5-4", "number": 4, "text": "What is displayed?\n```js\nalert(parseFloat(\"9.25\"));\n```", "options": ["9", "9.25", "9.3", "10"], "answer": 1, "why": "parseFloat parses the fractional part too."}, {"id": "m5-5", "number": 5, "text": "What is displayed?\n```js\nalert(parseFloat(\"7.00\"));\n```", "options": ["7", "7.0", "7.00", "\"7.00\" including quotes"], "answer": 0, "why": "A numeric value does not preserve the input text’s trailing zero formatting."}, {"id": "m5-6", "number": 6, "text": "Which browser function provides OK and Cancel and returns a boolean?", "options": ["confirm()", "alert()", "print()", "console.log()"], "answer": 0, "why": "confirm returns true for OK and false for Cancel."}, {"id": "m5-7", "number": 7, "text": "Calling window.print() writes text into the HTML page.", "options": ["True", "False"], "answer": 1, "why": "It opens the browser’s print flow; it is not a DOM text-output method."}, {"id": "m5-8", "number": 8, "text": "What is the result?\n```js\n\"Count: \" + 5 + 2\n```", "options": ["Count: 52", "Count: 7", "7", "An error"], "answer": 0, "why": "Once the left operand is a string, the + operations concatenate left to right."}, {"id": "m5-9", "number": 9, "text": "Which escape sequence represents a newline in a string?", "options": ["\\n", "/n", "\\t", "/newline"], "answer": 0, "why": "The backslash begins the escape sequence; forward slash does not."}], "source": "Assessment-based practice", "written": [{"id": "5-1", "number": 1, "text": "Give three ways JavaScript can be included in or linked from an HTML page."}, {"id": "5-2", "number": 2, "text": "A user enters 8.75 into prompt(). What is the returned data type before conversion? What happens if the user cancels?"}, {"id": "5-3", "number": 3, "text": "Compare the displayed values from `parseInt('8.75')` and `parseFloat('8.75')`."}, {"id": "5-4", "number": 4, "text": "Predict `alert(parseFloat('6.00'))`. Does parsing preserve the user's original decimal formatting?"}, {"id": "5-5", "number": 5, "text": "Which browser function would you use to obtain an OK/Cancel decision as a boolean? How does it differ from alert()?"}, {"id": "5-6", "number": 6, "text": "What is the purpose of browser print()? Does calling it insert a message into a paragraph?"}, {"id": "5-7", "number": 7, "text": "Predict `'Items: ' + 4 + 2`, then predict `'Items: ' + (4 + 2)`."}, {"id": "5-8", "number": 8, "text": "Write a string that displays a quoted nickname and then moves to a second line in an alert."}, {"id": "5-9", "number": 9, "text": "Compare the characters in `'First\\nSecond'` and `'First/nSecond'`."}]}, {"id": 6, "title": "Operators", "hint": "Expand compound assignments into full expressions. For equality questions, write both operands' types before deciding.", "questions": [{"id": "m6-1", "number": 1, "text": "What is the result of 15 / 4?", "options": ["3", "3.75", "4", "3.5"], "answer": 1, "why": "JavaScript Number division is not restricted to integer results."}, {"id": "m6-2", "number": 2, "text": "What is the result of 15 % 4?", "options": ["3", "3.75", "4", "0"], "answer": 0, "why": "15 equals three groups of 4 with a remainder of 3."}, {"id": "m6-3", "number": 3, "text": "What does Math.round(28.62) return?", "options": ["28", "29", "28.6", "28.62"], "answer": 1, "why": "Math.round returns the nearest integer."}, {"id": "m6-4", "number": 4, "text": "What is the result of (28.627).toFixed(2)?", "options": ["The string \"28.63\"", "The number 28", "The string \"28.62\"", "The number 29"], "answer": 0, "why": "toFixed rounds to a requested number of decimal places and returns a string."}, {"id": "m6-5", "number": 5, "text": "What is logged?\n```js\nlet n = 19;\nn %= 6;\nconsole.log(n);\n```", "options": ["1", "3", "6", "19"], "answer": 0, "why": "n %= 6 assigns the remainder of 19 divided by 6."}, {"id": "m6-6", "number": 6, "text": "What does \"14\" == 14 evaluate to?", "options": ["true", "false", "undefined", "An error"], "answer": 0, "why": "Loose equality can coerce the string to compare with the number."}, {"id": "m6-7", "number": 7, "text": "What does \"14\" === 14 evaluate to?", "options": ["true", "false", "undefined", "An error"], "answer": 1, "why": "Strict equality requires matching types as well as values."}, {"id": "m6-8", "number": 8, "text": "What does \"14\" !== 14 evaluate to?", "options": ["true", "false", "undefined", "An error"], "answer": 0, "why": "The types differ, so strict inequality is true."}], "source": "Assessment-based practice", "written": [{"id": "6-1", "number": 1, "text": "Predict `13 / 4` and `13 % 4`. Explain the difference."}, {"id": "6-2", "number": 2, "text": "Predict `Math.round(42.48)` and `Math.round(42.62)`."}, {"id": "6-3", "number": 3, "text": "Predict `(42.678).toFixed(2)` and `(42.678).toFixed(1)`. What data type do these methods return?"}, {"id": "6-4", "number": 4, "text": "Trace `let n = 17; n %= 5; console.log(n);`."}, {"id": "6-5", "number": 5, "text": "Compare `'12' == 12`, `'12' === 12`, and `'12' !== 12`. Explain the role of type in each."}, {"id": "6-6", "number": 6, "text": "Predict `let total = 9; total += 4; total *= 2; console.log(total);`."}, {"id": "6-7", "number": 7, "text": "A developer expects `'7' + 3` and `'7' * 3` to behave identically. What should they investigate?"}]}, {"id": 7, "title": "Selection", "hint": "First identify whether an expression produces a number or boolean. Trace branches in order, and remember string comparisons are case-sensitive.", "questions": [{"id": "m7-1", "number": 1, "text": "The if statement is an example of which control structure?", "options": ["Selection", "Repetition", "Invocation", "Top-down only"], "answer": 0, "why": "An if selects a branch based on a condition."}, {"id": "m7-2", "number": 2, "text": "An if condition in JavaScript must be enclosed in parentheses.", "options": ["True", "False"], "answer": 0, "why": "The syntax is if (condition), followed by the body."}, {"id": "m7-3", "number": 3, "text": "What is logged?\n```js\nlet n = 0;\nif (n = 5) console.log(\"A\");\nelse console.log(\"B\");\n```", "options": ["A", "B", "A then B", "A syntax error"], "answer": 0, "why": "The assignment produces 5, a truthy value. It also changes n."}, {"id": "m7-4", "number": 4, "text": "What is logged?\n```js\nlet n = 8;\nconsole.log(n < 8 ? \"Low\" : \"Other\");\n```", "options": ["Low", "Other", "Both", "Nothing"], "answer": 1, "why": "The less-than comparison is false when the values are equal."}, {"id": "m7-5", "number": 5, "text": "What is logged?\n```js\nlet color = \"Green\";\nif (color === \"green\") console.log(\"Same\");\nelse console.log(\"Different\");\n```", "options": ["Same", "Different", "Both", "A syntax error"], "answer": 1, "why": "String comparison is case-sensitive."}, {"id": "m7-6", "number": 6, "text": "Which correctly checks that n is greater than 2 and less than 9?", "options": ["n > 2 && n < 9", "n > 2 && < 9", "2 < n < 9", "n > 2 ", "", " n < 9"], "answer": 0, "why": "Both comparisons need their own operands, joined by &&."}, {"id": "m7-7", "number": 7, "text": "What is logged?\n```js\nlet n = 8;\nswitch (n === 8) {\n case 8: console.log(\"Number\"); break;\n default: console.log(\"Other\");\n}\n```", "options": ["Number", "Other", "Both", "A syntax error"], "answer": 1, "why": "The switch expression is boolean true, which does not strictly match numeric case 8."}, {"id": "m7-8", "number": 8, "text": "What is logged?\n```js\nswitch (2) {\n case 2: console.log(\"A\");\n case 3: console.log(\"B\"); break;\n default: console.log(\"C\");\n}\n```", "options": ["A only", "A then B", "B only", "C only"], "answer": 1, "why": "Without a break after A, execution falls through into the next case’s statements."}, {"id": "m7-9", "number": 9, "text": "In an if/else-if chain, what happens after the first true branch runs?", "options": ["Later branches are skipped", "All later true branches also run", "The program always ends", "Every condition is evaluated again"], "answer": 0, "why": "Only one branch of a single if/else-if/else chain runs."}], "source": "Assessment-based practice", "written": [{"id": "7-1", "number": 1, "text": "Which control structure is being used when the program chooses a branch based on a condition?"}, {"id": "7-2", "number": 2, "text": "Find the syntax problem in `if score >= 80 { alert('Pass'); }`."}, {"id": "7-3", "number": 3, "text": "Trace `let count = 0; if (count = 6) { console.log('A'); } else { console.log('B'); }`. What is count afterward? What operator would express a comparison instead?"}, {"id": "7-4", "number": 4, "text": "Predict `let age = 18; console.log(age > 18 ? 'older' : 'not older');`."}, {"id": "7-5", "number": 5, "text": "Trace the branches when points is 50: `if (points > 50) ... else if (points < 50) ... else ...`. Which branch is selected?"}, {"id": "7-6", "number": 6, "text": "With `let color = 'Blue'; let ready = true;`, evaluate `ready && color === 'blue'`. Explain each part."}, {"id": "7-7", "number": 7, "text": "Why is `if (n > 2 && < 9)` invalid? Rewrite the condition in your own attempt."}, {"id": "7-8", "number": 8, "text": "If the first branch of an if/else-if chain is true, can a later branch in that chain still run?"}, {"id": "7-9", "number": 9, "text": "Trace:\n```js\nlet level = 4;\nswitch (level === 4) {\n  case 4: console.log('Number'); break;\n  default: console.log('Other');\n}\n```"}, {"id": "7-10", "number": 10, "text": "Trace the same case values if the switch expression becomes `level` instead."}, {"id": "7-11", "number": 11, "text": "What is the purpose of break in a switch? Predict what could happen when a matching case lacks one."}, {"id": "7-12", "number": 12, "text": "Write an eligibility condition requiring age at least 18 AND consent, then another allowing membership OR a guest pass."}]}, {"id": 8, "title": "Repetition", "hint": "Check initialization and whether the update can make the condition false before attempting to calculate a final output.", "questions": [{"id": "m8-1", "number": 1, "text": "Which loop guarantees that its body runs at least once?", "options": ["do/while", "while", "for", "switch"], "answer": 0, "why": "A do/while tests the condition after the body."}, {"id": "m8-2", "number": 2, "text": "Which is a common choice for a known number of repetitions?", "options": ["for", "switch", "if", "return"], "answer": 0, "why": "A for loop conveniently groups counter initialization, test, and update."}, {"id": "m8-3", "number": 3, "text": "What is logged?\n```js\nlet total = 0;\nfor (let i = 1; i <= 3; i++) total += i;\nconsole.log(total);\n```", "options": ["3", "6", "7", "NaN"], "answer": 1, "why": "The loop adds 1, then 2, then 3 to the initial zero."}, {"id": "m8-4", "number": 4, "text": "What is logged?\n```js\nlet total;\nfor (let i = 0; i < 3; i++) total += i;\nconsole.log(total);\n```", "options": ["0", "3", "6", "NaN"], "answer": 3, "why": "The uninitialized total is undefined; adding a number produces NaN."}, {"id": "m8-5", "number": 5, "text": "What happens to this loop?\n```js\nfor (let i = 0; i < 4; i--) { }\n```", "options": ["It runs four times", "It runs zero times", "It does not normally terminate", "It has a syntax error"], "answer": 2, "why": "The decreasing counter moves away from making i < 4 false."}, {"id": "m8-6", "number": 6, "text": "How many times is Ready logged?\n```js\nfor (let i = 0; i < 4; i++);\nconsole.log(\"Ready\");\n```", "options": ["0", "1", "4", "5"], "answer": 1, "why": "The semicolon is the empty loop body; the log is after the loop."}, {"id": "m8-7", "number": 7, "text": "What two values are logged, in order?\n```js\nlet n = 4;\nconsole.log(n++);\nconsole.log(++n);\n```", "options": ["4, 6", "5, 6", "4, 5", "5, 5"], "answer": 0, "why": "Postfix yields 4 then increments to 5; prefix increments to 6 before yielding."}, {"id": "m8-8", "number": 8, "text": "What is logged?\n```js\nlet text = \"\";\nfor (let i = 6; i > 0; i -= 2) text += i;\nconsole.log(text);\n```", "options": ["642", "654321", "246", "12"], "answer": 0, "why": "The counter values 6, 4, 2 are concatenated to a string."}], "source": "Assessment-based practice", "written": [{"id": "8-1", "number": 1, "text": "Choose a loop for each: repeat a known number of times; repeat until valid input is received; show a menu at least once before testing whether to continue."}, {"id": "8-2", "number": 2, "text": "Trace `let total = 0; for (let i = 1; i <= 4; i++) { total += i; }`. List the i values used."}, {"id": "8-3", "number": 3, "text": "What changes if total is declared without being initialized before that loop?"}, {"id": "8-4", "number": 4, "text": "Does `for (let i = 0; i < 4; i--)` move toward or away from termination? Would an alert after the loop normally be reached?"}, {"id": "8-5", "number": 5, "text": "How many times does this display Ready?\n```js\nfor (let i = 0; i < 4; i++);\nconsole.log('Ready');\n```"}, {"id": "8-6", "number": 6, "text": "Predict both outputs: `let n = 5; console.log(n++); console.log(++n);`."}, {"id": "8-7", "number": 7, "text": "Trace `let n = 3; console.log(--n); console.log(n);`."}, {"id": "8-8", "number": 8, "text": "Trace `let text = ''; for (let i = 6; i > 0; i -= 2) { text += i; } console.log(text);`."}, {"id": "8-9", "number": 9, "text": "What would change if the update in the preceding loop were i += 2?"}, {"id": "8-10", "number": 10, "text": "How many times does a while loop run if its initial condition is false? Compare with do/while."}, {"id": "8-11", "number": 11, "text": "Use a trace table to explain the initializer, condition, body, and update in a for loop."}]}, {"id": 9, "title": "Built-in functions", "hint": "Build the index row yourself. Negative rounding and reversed substring bounds deserve particular care.", "questions": [{"id": "m9-1", "number": 1, "text": "What does Math.ceil(73.2) return?", "options": ["73", "74", "73.2", "72"], "answer": 1, "why": "ceil rounds upward toward positive infinity."}, {"id": "m9-2", "number": 2, "text": "What does Math.floor(-19.8) return?", "options": ["-19", "-20", "19", "20"], "answer": 1, "why": "floor rounds downward toward negative infinity."}, {"id": "m9-3", "number": 3, "text": "What does Math.trunc(-19.8) return?", "options": ["-19", "-20", "19", "20"], "answer": 0, "why": "trunc discards the fractional portion, moving toward zero."}, {"id": "m9-4", "number": 4, "text": "What is (4.567).toPrecision(3)?", "options": ["\"4.57\"", "\"4.567\"", "\"4.560\"", "\"4.56\""], "answer": 0, "why": "Precision counts significant digits, rounding at the requested precision."}, {"id": "m9-5", "number": 5, "text": "What does Number.isInteger(\"8\") return?", "options": ["true", "false", "8", "undefined"], "answer": 1, "why": "Number.isInteger does not convert the string into a number."}, {"id": "m9-6", "number": 6, "text": "What does \"Silver Moon\".slice(7, 11) return?", "options": ["Moon", "Moo", "Silver", "An empty string"], "answer": 0, "why": "slice includes index 7 and excludes index 11."}, {"id": "m9-7", "number": 7, "text": "What does \"Silver Moon\".charAt(6) return?", "options": ["A space", "M", "r", "An empty string"], "answer": 0, "why": "Indices start at zero; index 6 is the separating space."}, {"id": "m9-8", "number": 8, "text": "What does \"Silver Moon\".indexOf(\"z\") return?", "options": ["0", "-1", "undefined", "An error"], "answer": 1, "why": "indexOf returns -1 when no match exists."}, {"id": "m9-9", "number": 9, "text": "What does \"Silver Moon\".startsWith(\"silver\") return?", "options": ["true", "false", "\"Silver\"", "An error"], "answer": 1, "why": "startsWith is case-sensitive."}, {"id": "m9-10", "number": 10, "text": "What does \"Silver Moon\".slice(8, 3) return?", "options": ["An empty string", "\"ver M\"", "\"oon\"", "An error"], "answer": 0, "why": "For these positive bounds, slice does not swap start and end."}, {"id": "m9-11", "number": 11, "text": "What does \"Silver Moon\".substring(8, 3) return?", "options": ["\"ver M\"", "An empty string", "\"oon\"", "An error"], "answer": 0, "why": "substring swaps these reversed bounds, extracting indices 3 through 7."}, {"id": "m9-12", "number": 12, "text": "The legacy substr(start, length) method’s second argument specifies:", "options": ["Number of characters", "End index", "Start index", "String type"], "answer": 0, "why": "Unlike slice, substr uses a length. It is a legacy method included in the course."}], "source": "Assessment-based practice", "written": [{"id": "9-1", "number": 1, "text": "With cost = 83.26, predict Math.ceil(cost), Math.floor(cost), and Math.round(cost)."}, {"id": "9-2", "number": 2, "text": "With debt = -47.8, compare Math.floor(debt), Math.ceil(debt), Math.trunc(debt), and Math.round(debt)."}, {"id": "9-3", "number": 3, "text": "Compare `(12.345).toPrecision(4)` and `(12.345).toFixed(4)`. What does each argument count?"}, {"id": "9-4", "number": 4, "text": "Evaluate Number.isInteger(7), Number.isInteger(7.2), and Number.isInteger('7')."}, {"id": "9-5", "number": 5, "text": "Predict `let amount; console.log(amount * 3);`."}, {"id": "9-6", "number": 6, "text": "Using `let title = 'Cloud Study Notes';`, write down every character's zero-based index, including spaces."}, {"id": "9-7", "number": 7, "text": "Using that title, predict title.slice(6, 11), title.charAt(5), and title.length."}, {"id": "9-8", "number": 8, "text": "Predict title.startsWith('cloud'), title.endsWith('Notes'), title.indexOf('o'), and title.lastIndexOf('Z')."}, {"id": "9-9", "number": 9, "text": "What does title.replace('Study', 'Review') return? Is title itself changed without an assignment?"}, {"id": "9-10", "number": 10, "text": "Compare title.slice(11, 6) with title.substring(11, 6)."}, {"id": "9-11", "number": 11, "text": "Your course includes the legacy substr() method. Compare title.substr(6, 5) with title.slice(6, 5); what does the second argument mean in each?"}]}, {"id": 10, "title": "Custom functions", "hint": "Track parameters separately from the caller's variables. Keep declaration, initialization, and return value distinct.", "questions": [{"id": "m10-1", "number": 1, "text": "Why create functions?", "options": ["Reduce duplication", "Improve reuse", "Organize logic", "All of these"], "answer": 3, "why": "Functions give repeated or cohesive logic a reusable name."}, {"id": "m10-2", "number": 2, "text": "JavaScript limits every function name to 30 characters.", "options": ["True", "False"], "answer": 1, "why": "That is not a JavaScript language naming limit."}, {"id": "m10-3", "number": 3, "text": "What is logged?\n```js\nfunction sum(a, b) { return a + b; }\nconsole.log(sum(4));\n```", "options": ["4", "NaN", "0", "A syntax error"], "answer": 1, "why": "The omitted argument b is undefined, so the addition produces NaN."}, {"id": "m10-4", "number": 4, "text": "Every JavaScript function must include a return statement.", "options": ["True", "False"], "answer": 1, "why": "A function may have no explicit return; its result is then undefined."}, {"id": "m10-5", "number": 5, "text": "For a = 3 and b = 7, what does return (a, b) return?", "options": ["An array [3, 7]", "7", "3", "Two separate return values"], "answer": 1, "why": "The comma operator evaluates both expressions and yields the last."}, {"id": "m10-6", "number": 6, "text": "A let variable declared inside a block is scoped to that block.", "options": ["True", "False"], "answer": 0, "why": "let is block-scoped."}, {"id": "m10-7", "number": 7, "text": "What is logged?\n```js\nlet n = 2;\n{ let n = 9; }\nconsole.log(n);\n```", "options": ["2", "9", "undefined", "A syntax error"], "answer": 0, "why": "The inner binding shadows the outer binding without changing it."}, {"id": "m10-8", "number": 8, "text": "Redeclaring const score in the same scope is a valid way to change its value.", "options": ["True", "False"], "answer": 1, "why": "A const binding cannot be redeclared in the same scope."}, {"id": "m10-9", "number": 9, "text": "A const array can have elements added without assigning a new array to its variable.", "options": ["True", "False"], "answer": 0, "why": "const prevents rebinding; it does not freeze the array."}, {"id": "m10-10", "number": 10, "text": "Which arrow function returns twice its argument?", "options": ["x => x * 2", "x => { x * 2; }", "x -> x * 2", "=> x * 2"], "answer": 0, "why": "An expression body returns implicitly; a block body needs return for this result."}], "source": "Assessment-based practice", "written": [{"id": "10-1", "number": 1, "text": "Give three reasons to move repeated code into a function."}, {"id": "10-2", "number": 2, "text": "True or false: a JavaScript function name has a language-imposed maximum of 30 characters. Explain how naming rules differ from style conventions."}, {"id": "10-3", "number": 3, "text": "Trace `function add(a, b) { return a + b; } console.log(add(5));`. What happens to the missing argument?"}, {"id": "10-4", "number": 4, "text": "What does a function call evaluate to if the function reaches its end without returning a value?"}, {"id": "10-5", "number": 5, "text": "Explain what `return (a, b);` does. Does this automatically return a pair? Propose a structure that could represent a pair."}, {"id": "10-6", "number": 6, "text": "Contrast global, function, and block scope. Why can heavy use of globals complicate debugging?"}, {"id": "10-7", "number": 7, "text": "Trace `let n = 3; { let n = 8; } console.log(n);`."}, {"id": "10-8", "number": 8, "text": "What problem occurs with `const rate = 4; const rate = 7;` in the same scope?"}, {"id": "10-9", "number": 9, "text": "Can a const array gain a new element? Distinguish changing an object from replacing a binding."}, {"id": "10-10", "number": 10, "text": "Compare reading a var variable before its declaration with reading a let variable before its declaration. Do they have identical behavior?"}, {"id": "10-11", "number": 11, "text": "Rewrite a short function as an arrow function with one parameter. When can parameter parentheses be omitted?"}, {"id": "10-12", "number": 12, "text": "An arrow function has braces and two statements but no return. Can you assume its last expression is returned?"}]}, {"id": 11, "title": "Arrays", "hint": "Missing array positions and misspelled variable names are different problems. Default sort compares string representations.", "questions": [{"id": "m11-1", "number": 1, "text": "Which is a valid JavaScript array?", "options": ["[3, \"yes\", false]", "Only arrays of numbers are valid", "Only arrays of strings are valid", "Mixed types require a class"], "answer": 0, "why": "Arrays can hold different value types."}, {"id": "m11-2", "number": 2, "text": "What is the length of Array(6)?", "options": ["0", "5", "6", "1"], "answer": 2, "why": "A single numeric argument creates an array with that length and empty slots."}, {"id": "m11-3", "number": 3, "text": "For an array of length 6, what is the last index?", "options": ["6", "5", "7", "1"], "answer": 1, "why": "Zero-based indices run from 0 through length - 1."}, {"id": "m11-4", "number": 4, "text": "What is logged?\n```js\nlet names = [\"Kai\", \"Zoe\"];\nconsole.log(names[4]);\n```", "options": ["undefined", "null", "Zoe", "A ReferenceError"], "answer": 0, "why": "An absent array position returns undefined when the array itself exists."}, {"id": "m11-5", "number": 5, "text": "What is a.length afterward?\n```js\nlet a = [];\na[3] = \"book\";\n```", "options": ["1", "3", "4", "0"], "answer": 2, "why": "Assigning index 3 extends length to 4, leaving earlier slots empty."}, {"id": "m11-6", "number": 6, "text": "Which method removes the first array element?", "options": ["shift()", "pop()", "push()", "unshift()"], "answer": 0, "why": "shift removes from the beginning; pop removes from the end."}, {"id": "m11-7", "number": 7, "text": "Which method adds an element at the beginning?", "options": ["push()", "unshift()", "pop()", "shift()"], "answer": 1, "why": "unshift adds at the beginning."}, {"id": "m11-8", "number": 8, "text": "What does reverse() do?", "options": ["Reverse existing element order", "Sort from greatest to least automatically", "Sort alphabetically", "Remove every element"], "answer": 0, "why": "Reversal and sorting are different operations."}, {"id": "m11-9", "number": 9, "text": "What is the default sorted order of [\"pear\", \"Apple\", \"Zebra\"]?", "options": ["Apple, Zebra, pear", "Apple, pear, Zebra", "pear, Zebra, Apple", "Zebra, pear, Apple"], "answer": 0, "why": "Default sort compares string representations, including case."}, {"id": "m11-10", "number": 10, "text": "forEach requires a three-part initializer; condition; update header.", "options": ["True", "False"], "answer": 1, "why": "forEach invokes a callback for array elements rather than using that header."}], "source": "Assessment-based practice", "written": [{"id": "11-1", "number": 1, "text": "Is `[17, 'Landon', false]` a valid JavaScript array? Explain."}, {"id": "11-2", "number": 2, "text": "Compare `Array(4)`, `[]`, and `[4]`: what is each array's length, and does each contain a numeric element?"}, {"id": "11-3", "number": 3, "text": "With `let names = ['Ava', 'Noah', 'Mia'];`, predict names[2] and names[5]."}, {"id": "11-4", "number": 4, "text": "What happens if code instead reads namez[5], where namez has never been declared? Contrast with the previous question."}, {"id": "11-5", "number": 5, "text": "Trace `let items = []; items[4] = 'book';`. What is items.length? What is found at index 0?"}, {"id": "11-6", "number": 6, "text": "What is the last possible index in an array whose length is 8?"}, {"id": "11-7", "number": 7, "text": "Match push, pop, shift, and unshift with the end of the array they add to or remove from."}, {"id": "11-8", "number": 8, "text": "Trace `let a = ['red', 'blue']; a.push('green'); a.shift(); a.unshift('gold'); console.log(a);`."}, {"id": "11-9", "number": 9, "text": "Predict the ordering after `['pear', 'Apple', 'Zebra', 'banana'].sort()`."}, {"id": "11-10", "number": 10, "text": "Predict the ordering after `['pear', 'Apple', 'Zebra', 'banana'].reverse()`. Does reverse perform a descending sort?"}, {"id": "11-11", "number": 11, "text": "Does forEach use the same three-part header as a traditional for loop? Describe what its callback receives."}, {"id": "11-12", "number": 12, "text": "Write an attempt to visit every array element without accessing an index equal to length."}]}, {"id": 12, "title": "Debugging", "hint": "Ask whether the program cannot be parsed, fails during execution, or executes successfully with the wrong result.", "questions": [{"id": "m12-1", "number": 1, "text": "A missing closing parenthesis is usually a:", "options": ["Syntax error", "Logic error", "Schedule error", "Data structure"], "answer": 0, "why": "The program’s syntax is malformed."}, {"id": "m12-2", "number": 2, "text": "A program runs but uses the wrong discount formula. This is a:", "options": ["Logic error", "Syntax error", "Markup type", "Package error"], "answer": 0, "why": "The program executes but its algorithm gives the wrong result."}, {"id": "m12-3", "number": 3, "text": "Attempting to read a property of null during execution causes a:", "options": ["Runtime error", "Scheduling error", "CSS rule", "Comment"], "answer": 0, "why": "The operation fails when execution reaches it."}, {"id": "m12-4", "number": 4, "text": "Experienced developers can still benefit from breakpoints and a debugger.", "options": ["True", "False"], "answer": 0, "why": "A debugger lets you inspect actual execution and values."}, {"id": "m12-5", "number": 5, "text": "An untested branch might hide an error until a user eventually executes it.", "options": ["True", "False"], "answer": 0, "why": "Testing only common paths can leave defects undiscovered."}, {"id": "m12-6", "number": 6, "text": "A button does nothing. Which is the best first debugging step?", "options": ["Inspect console errors and whether its handler runs", "Rewrite the entire app", "Delete all variables", "Ignore the failure"], "answer": 0, "why": "Observe the failure and narrow its cause before changing code."}], "source": "Assessment-based practice", "written": [{"id": "12-1", "number": 1, "text": "Classify each: a missing closing parenthesis; accessing a property of null; calculating a discount with the wrong percentage."}, {"id": "12-2", "number": 2, "text": "A function fails only when a rarely used button is clicked. Why might the error have remained hidden during testing?"}, {"id": "12-3", "number": 3, "text": "Where would you place a breakpoint if clicking Add changes a legend but does not display the form?"}, {"id": "12-4", "number": 4, "text": "Describe what you would inspect in variables and DOM state while paused at that breakpoint."}, {"id": "12-5", "number": 5, "text": "True or false: experienced developers should avoid debuggers. Explain your reasoning."}, {"id": "12-6", "number": 6, "text": "A deadline is close. What risks arise if only the happy path has been tested?"}, {"id": "12-7", "number": 7, "text": "How could you use documentation or a peer to investigate a bug while still verifying the proposed fix yourself?"}, {"id": "12-8", "number": 8, "text": "The course mentions a famous moth incident. What did that incident document? Distinguish the anecdote from the broader history of the term bug."}]}, {"id": 13, "title": "Events", "hint": "Separate registering a response from running it. One HTML element can respond to different events.", "questions": [{"id": "m13-1", "number": 1, "text": "What is the main purpose of an event handler?", "options": ["Respond to an event", "Declare a database", "Replace CSS", "Compile HTML"], "answer": 0, "why": "Handlers connect events with application behavior."}, {"id": "m13-2", "number": 2, "text": "A function called by a click handler may execute several statements.", "options": ["True", "False"], "answer": 0, "why": "A handler can call a function that performs multiple operations."}, {"id": "m13-3", "number": 3, "text": "Which button calls showSummary when clicked?", "options": ["<button onclick=\"showSummary()\">Show</button>", "<button click=\"showSummary\">Show</button>", "<button onclick=\"showSummary\">Show</button>", "<button href=\"showSummary()\">Show</button>"], "answer": 0, "why": "The inline onclick expression calls the function with parentheses."}, {"id": "m13-4", "number": 4, "text": "Two different buttons can both have onclick handlers.", "options": ["True", "False"], "answer": 0, "why": "Each element can respond to its own events."}, {"id": "m13-5", "number": 5, "text": "An element can respond to both a click event and a change event.", "options": ["True", "False"], "answer": 0, "why": "Different event types can be handled on the same element."}, {"id": "m13-6", "number": 6, "text": "When registering a listener, which passes a function to be called later?", "options": ["button.addEventListener(\"click\", showSummary)", "button.addEventListener(\"click\", showSummary())", "button.addEventListener(showSummary, \"click\")", "button.addEvent(\"click\", showSummary)"], "answer": 0, "why": "Passing the reference registers it; calling it immediately passes its result instead."}], "source": "Assessment-based practice", "written": [{"id": "13-1", "number": 1, "text": "Explain the relationship among a user's action, an event, and an event handler."}, {"id": "13-2", "number": 2, "text": "Write a button whose inline onclick handler calls a function named showSummary."}, {"id": "13-3", "number": 3, "text": "Can the function called by a handler perform several operations, such as updating text and hiding a form?"}, {"id": "13-4", "number": 4, "text": "Show how quotes delimit an inline event attribute. What problem occurs if an inner string uses conflicting quotes?"}, {"id": "13-5", "number": 5, "text": "Could one input respond to both a click and a change event? Could two different buttons both use onclick?"}, {"id": "13-6", "number": 6, "text": "Compare passing a function reference to addEventListener with calling that function while registering the listener. When would each execute?"}]}, {"id": 14, "title": "The DOM", "hint": "Spell the DOM method exactly. After selection, determine whether you have an element, a collection, or null.", "questions": [{"id": "m14-1", "number": 1, "text": "In HTTP communication, the client sends a ___ and the server sends a ___.", "options": ["request; response", "response; request", "table; column", "class; instance"], "answer": 0, "why": "A request asks the server for work or a resource; the server replies with a response."}, {"id": "m14-2", "number": 2, "text": "An HTML element is represented in the DOM as a:", "options": ["Node", "SQL record", "Package", "Compiler"], "answer": 0, "why": "The DOM models the document as a tree of nodes."}, {"id": "m14-3", "number": 3, "text": "Which selects an element with id=\"message\"?", "options": ["document.getElementById(\"message\")", "document.getElementsById(\"message\")", "document.getElementByClass(\"message\")", "document.getElementByTagName(\"message\")"], "answer": 0, "why": "getElementById selects one element by its ID."}, {"id": "m14-4", "number": 4, "text": "Which correctly selects elements with class=\"notice\"?", "options": ["document.getElementsByClassName(\"notice\")", "document.getElementByClassName(\"notice\")", "document.getElementByClass(\"notice\")", "document.getElementsByClass(\"notice\")"], "answer": 0, "why": "The method includes Elements, plural, and returns a collection."}, {"id": "m14-5", "number": 5, "text": "Which correctly selects all paragraph elements?", "options": ["document.getElementsByTagName(\"p\")", "document.getElementByTagName(\"p\")", "document.getElementsByTag(\"p\")", "document.getElementById(\"p\")"], "answer": 0, "why": "getElementsByTagName returns a collection matching a tag name."}, {"id": "m14-6", "number": 6, "text": "An ID should be unique, while a class can be used by multiple elements.", "options": ["True", "False"], "answer": 0, "why": "IDs identify individual elements; classes group elements."}, {"id": "m14-7", "number": 7, "text": "Which displays the literal characters <b>Hello</b> as text?", "options": ["element.textContent = \"<b>Hello</b>\"", "element.innerHTML = \"<b>Hello</b>\"", "element.valueAsNumber = \"<b>Hello</b>\"", "element.style = \"<b>Hello</b>\""], "answer": 0, "why": "textContent inserts text, while innerHTML interprets markup."}, {"id": "m14-8", "number": 8, "text": "If getElementById cannot find an element, it returns:", "options": ["null", "An empty array", "0", "false"], "answer": 0, "why": "Check the ID and whether the element exists when selection runs."}], "source": "Assessment-based practice", "written": [{"id": "14-1", "number": 1, "text": "A browser asks a server for a webpage. Which side sends the request, and which sends the response?"}, {"id": "14-2", "number": 2, "text": "Explain what a node is in the DOM tree and how it relates to an HTML element."}, {"id": "14-3", "number": 3, "text": "Given `<p id=\"statusMessage\">Waiting</p>`, write an attempt to select the paragraph by ID."}, {"id": "14-4", "number": 4, "text": "Given two paragraphs with `class=\"notice\"`, choose the correctly spelled method: getElementByClass, getElementByClassName, or getElementsByClassName. Does it return one element or a collection?"}, {"id": "14-5", "number": 5, "text": "How would you select all paragraph elements by tag name? Check singular versus plural carefully."}, {"id": "14-6", "number": 6, "text": "Why should an ID be unique while a class can be reused?"}, {"id": "14-7", "number": 7, "text": "You receive a collection of elements. What additional step is needed to change only the first element?"}, {"id": "14-8", "number": 8, "text": "Compare assigning `'Hello <b>Landon</b>'` to textContent versus innerHTML."}, {"id": "14-9", "number": 9, "text": "A selection by ID returns null. Name two concrete things to check before changing the assignment that follows it."}]}, {"id": 15, "title": "HTML forms", "hint": "Read the actual tag and button type. Native form validation is tied to the submission flow.", "questions": [{"id": "m15-1", "number": 1, "text": "How can a label be associated with an input?", "options": ["Use for matching the input ID", "Nest the input inside the label", "Either approach", "Only through JavaScript"], "answer": 2, "why": "Both explicit for/id association and implicit nesting are valid."}, {"id": "m15-2", "number": 2, "text": "Every label automatically starts on its own line.", "options": ["True", "False"], "answer": 1, "why": "Labels are inline by default; layout depends on markup and CSS."}, {"id": "m15-3", "number": 3, "text": "Which button type normally initiates form submission?", "options": ["submit", "button", "text", "password"], "answer": 0, "why": "A submit button participates in the form’s submission flow."}, {"id": "m15-4", "number": 4, "text": "What does action=\"/register\" normally specify on a form?", "options": ["The submission destination URL", "The required JavaScript function name", "The input’s ID", "The HTTP method"], "answer": 0, "why": "action is a URL destination. An event handler is a separate mechanism."}, {"id": "m15-5", "number": 5, "text": "Which method typically places form data in the URL query string?", "options": ["GET", "POST", "Both always", "Neither"], "answer": 0, "why": "GET commonly includes submitted data in the query string; POST usually uses the request body."}, {"id": "m15-6", "number": 6, "text": "A fieldset must have a legend for the HTML to be parsed.", "options": ["True", "False"], "answer": 1, "why": "A legend is useful for labeling the group but is not required for parsing."}, {"id": "m15-7", "number": 7, "text": "Which property reads the text entered into an input?", "options": ["value", "innerHTML", "textContent", "parseInt"], "answer": 0, "why": "The input’s value holds its current entered data."}, {"id": "m15-8", "number": 8, "text": "The rows and cols attributes enforce a textarea’s maximum character count.", "options": ["True", "False"], "answer": 1, "why": "They control visible dimensions. maxlength controls a character limit."}, {"id": "m15-9", "number": 9, "text": "Which attribute commonly supplies tooltip text?", "options": ["title", "required", "placeholder", "method"], "answer": 0, "why": "title commonly provides advisory text displayed as a tooltip."}, {"id": "m15-10", "number": 10, "text": "Why might onclick run on an ordinary button even with an empty required field?", "options": ["Clicking type=\"button\" does not initiate native form submission validation", "required is never supported", "The field is automatically valid", "JavaScript cannot read inputs"], "answer": 0, "why": "Native required validation belongs to the submission flow, not every button click."}], "source": "Assessment-based practice", "written": [{"id": "15-1", "number": 1, "text": "Show two different ways to associate a label with an input so clicking the label focuses the input."}, {"id": "15-2", "number": 2, "text": "Does a label automatically start a new line? What could control its layout instead?"}, {"id": "15-3", "number": 3, "text": "Explain how a submit button differs from a button with type=\"button\"."}, {"id": "15-4", "number": 4, "text": "In `<form action=\"/register\" method=\"post\">`, what does action specify? Distinguish a destination from an event handler."}, {"id": "15-5", "number": 5, "text": "Compare GET and POST form submissions. Where is submitted data typically placed in each?"}, {"id": "15-6", "number": 6, "text": "What are fieldset and legend used for? Is legend compulsory for the HTML to be parsed?"}, {"id": "15-7", "number": 7, "text": "Which property retrieves what a user typed into a text input: value, innerHTML, or textContent?"}, {"id": "15-8", "number": 8, "text": "Do rows and cols on a textarea enforce a character limit? What attribute would address length instead?"}, {"id": "15-9", "number": 9, "text": "Distinguish title, placeholder, and required on an input."}, {"id": "15-10", "number": 10, "text": "A required field remains empty, yet an ordinary button's onclick still runs. What difference between button clicks and form submission should you investigate?"}, {"id": "15-11", "number": 11, "text": "A fieldset looks too wide. Where would you adjust its presentation, and how would you verify the result in the browser?"}]}, {"id": 16, "title": "More form inputs", "hint": "Appearance, selection state, submitted value, and security are separate questions.", "questions": [{"id": "m16-1", "number": 1, "text": "Which input type masks entered characters?", "options": ["password", "hidden", "range", "radio"], "answer": 0, "why": "A password field hides the display of typed characters; it is not encryption."}, {"id": "m16-2", "number": 2, "text": "Which input type presents a slider?", "options": ["range", "number", "text", "checkbox"], "answer": 0, "why": "range provides a slider for a bounded numeric value."}, {"id": "m16-3", "number": 3, "text": "What groups mutually exclusive radio choices?", "options": ["A shared name attribute", "An identical ID for every choice", "The same label text", "The same title"], "answer": 0, "why": "Radios with the same name in a group are mutually exclusive."}, {"id": "m16-4", "number": 4, "text": "A form may contain more than one radio button group.", "options": ["True", "False"], "answer": 0, "why": "Different name values can define separate groups."}, {"id": "m16-5", "number": 5, "text": "Which property tells whether a checkbox is selected?", "options": ["checked", "value", "innerHTML", "title"], "answer": 0, "why": "checked is a boolean selection state; value is the associated submitted value."}, {"id": "m16-6", "number": 6, "text": "A datalist always restricts the user to its listed suggestions.", "options": ["True", "False"], "answer": 1, "why": "A datalist supplies suggestions but allows other input."}, {"id": "m16-7", "number": 7, "text": "What time is represented by 2026-10-16T17:35?", "options": ["5:35 PM", "5:35 AM", "7:35 PM", "10:16 PM"], "answer": 0, "why": "17:35 is a 24-hour time; datetime-local does not include a timezone offset."}, {"id": "m16-8", "number": 8, "text": "Which input type stores a value without displaying a normal control?", "options": ["hidden", "password", "number", "select"], "answer": 0, "why": "Hidden inputs are omitted from the normal display but can still be inspected and changed."}, {"id": "m16-9", "number": 9, "text": "Hidden inputs are a secure place to store secrets that the user cannot inspect.", "options": ["True", "False"], "answer": 1, "why": "Hidden affects presentation, not confidentiality."}], "source": "Assessment-based practice", "written": [{"id": "16-1", "number": 1, "text": "Choose suitable controls for a masked password, a numeric quantity, and a slider for volume."}, {"id": "16-2", "number": 2, "text": "Does masking a password field make its value encrypted or inaccessible to JavaScript?"}, {"id": "16-3", "number": 3, "text": "A form has two radio groups: membership and payment frequency. How would their name attributes preserve separate groups?"}, {"id": "16-4", "number": 4, "text": "Compare radio buttons with checkboxes when multiple choices should be allowed."}, {"id": "16-5", "number": 5, "text": "What property tells you whether a specific checkbox or radio button is selected? Is its value property the same thing?"}, {"id": "16-6", "number": 6, "text": "Can a datalist provide suggestions while allowing a user to enter an unlisted value? Compare with a select element."}, {"id": "16-7", "number": 7, "text": "Interpret the time in `2026-10-15T18:40` from a datetime-local input. Does this value include a timezone offset?"}, {"id": "16-8", "number": 8, "text": "What purpose does a hidden input serve? Is it safe to treat it as a secret that users cannot inspect or change?"}, {"id": "16-9", "number": 9, "text": "A number input should accept quantities from 1 through 10 in whole units. Which attributes would you investigate?"}]}, {"id": 17, "title": "Data structures", "hint": "Draw arrows for references. For a stack or queue, decide which arrival is removed first.", "questions": [{"id": "m17-1", "number": 1, "text": "Which structure removes the most recently added item first?", "options": ["Stack", "Queue", "Unordered database", "String"], "answer": 0, "why": "A stack follows last-in, first-out order."}, {"id": "m17-2", "number": 2, "text": "Which structure removes the earliest added item first?", "options": ["Queue", "Stack", "Class definition", "CSS selector"], "answer": 0, "why": "A queue follows first-in, first-out order."}, {"id": "m17-3", "number": 3, "text": "A, B, and C enter a stack in that order. Which is removed first?", "options": ["C", "A", "B", "All simultaneously"], "answer": 0, "why": "C is the most recently added item."}, {"id": "m17-4", "number": 4, "text": "A, B, and C enter a queue in that order. Which is removed first?", "options": ["A", "C", "B", "All simultaneously"], "answer": 0, "why": "A has waited longest."}, {"id": "m17-5", "number": 5, "text": "JavaScript arrays are mutable.", "options": ["True", "False"], "answer": 0, "why": "Their elements can change without replacing the array object."}, {"id": "m17-6", "number": 6, "text": "What is logged?\n```js\nlet a = [1];\nlet b = a;\nb.push(2);\nconsole.log(a.length);\n```", "options": ["1", "2", "0", "An error"], "answer": 1, "why": "Both variables refer to the same array, which is mutated."}], "source": "Lesson-based practice", "written": [{"id": "17-1", "number": 1, "text": "Explain mutable versus immutable using an array and a string."}, {"id": "17-2", "number": 2, "text": "Trace `let a = ['A']; let b = a; b.push('B'); console.log(a);`. Draw the references before predicting."}, {"id": "17-3", "number": 3, "text": "Compare changing an array element with assigning a different array to the variable."}, {"id": "17-4", "number": 4, "text": "Three items enter a stack in the order red, blue, green. In what order would three removals return them?"}, {"id": "17-5", "number": 5, "text": "Repeat the preceding question for a queue."}, {"id": "17-6", "number": 6, "text": "Choose a stack or queue for an undo history and for a line of pending customer requests. Explain the access order needed."}, {"id": "17-7", "number": 7, "text": "How could an array contain other arrays? Give an example of accessing one inner element."}, {"id": "17-8", "number": 8, "text": "What is the broad purpose of garbage collection? Why should a program still avoid keeping references to objects it no longer needs?"}]}, {"id": 18, "title": "OOP explained", "hint": "Ask where the value belongs: a temporary method call, an individual object, or the class itself.", "questions": [{"id": "m18-1", "number": 1, "text": "Which is the template used to create instances?", "options": ["Class", "Object instance", "Property value", "Method call"], "answer": 0, "why": "A class defines how instances are constructed and behave."}, {"id": "m18-2", "number": 2, "text": "An object’s name and age are examples of:", "options": ["Attributes", "Method calls", "Packages", "Loops"], "answer": 0, "why": "Attributes store an object’s characteristics or state."}, {"id": "m18-3", "number": 3, "text": "A function associated with an object is a:", "options": ["Method", "Record", "Column", "Stylesheet"], "answer": 0, "why": "A method supplies behavior associated with the object or class."}, {"id": "m18-4", "number": 4, "text": "When is a constructor called?", "options": ["When a new instance is created", "Only when a method is overridden", "Only when the page closes", "Every time a field is read"], "answer": 0, "why": "Construction initializes the new instance."}, {"id": "m18-5", "number": 5, "text": "Which is valid constructor syntax inside class Book?", "options": ["constructor(title) { this.title = title; }", "Book(self) { }", "def __init__(self):", "constructor Book() { }"], "answer": 0, "why": "JavaScript uses the constructor method name inside a class."}, {"id": "m18-6", "number": 6, "text": "Which keyword defines a field shared through the class rather than per instance?", "options": ["static", "const", "let", "return"], "answer": 0, "why": "A static field belongs to the class rather than individual instances."}, {"id": "m18-7", "number": 7, "text": "Which accesses a static field count defined on class Client?", "options": ["Client.count", "Every instance automatically has its own count", "this.count in any unrelated function", "count.Client"], "answer": 0, "why": "Access the static field through the class object."}, {"id": "m18-8", "number": 8, "text": "Two separately created objects with identical property values must have the same identity.", "options": ["True", "False"], "answer": 1, "why": "Distinct objects have distinct identities even if their contents match."}, {"id": "m18-9", "number": 9, "text": "Inside an instance method, this.total = 0 creates or sets a:", "options": ["Property on the receiver object", "Local let variable only", "Static field automatically", "New class"], "answer": 0, "why": "this refers to the receiver for an ordinary method call."}, {"id": "m18-10", "number": 10, "text": "A static field can never change its value.", "options": ["True", "False"], "answer": 1, "why": "static controls where the field belongs, not whether its value can change."}], "source": "Assessment-based practice", "written": [{"id": "18-1", "number": 1, "text": "Explain class versus object using a Client class and two client profiles."}, {"id": "18-2", "number": 2, "text": "Classify a client's name, workout recommendation, and calculateMinutes() as attributes or methods."}, {"id": "18-3", "number": 3, "text": "When does a constructor run? Can it receive parameters? What happens if a class has no explicitly written constructor?"}, {"id": "18-4", "number": 4, "text": "Write an attempt at a class named Book with a constructor receiving a title. Use valid JavaScript constructor syntax."}, {"id": "18-5", "number": 5, "text": "Contrast an instance field with a static field. Which is appropriate for one client's name and which for a shared count of created clients?"}, {"id": "18-6", "number": 6, "text": "Should a static field be accessed through the class or automatically through every instance? Explain."}, {"id": "18-7", "number": 7, "text": "Two objects have identical attributes. Does that make them the same object identity?"}, {"id": "18-8", "number": 8, "text": "What does this refer to in an ordinary instance method called on a client object?"}, {"id": "18-9", "number": 9, "text": "Compare `let score = 0;` inside a method with `this.score = 0;`. Which value can be accessed later through the object?"}, {"id": "18-10", "number": 10, "text": "A method creates this.lastViewed only when called. Would that field necessarily exist on a new object before the method runs?"}, {"id": "18-11", "number": 11, "text": "Does static mean a field's value can never change? Distinguish it from const."}]}, {"id": 19, "title": "Advanced OOP", "hint": "Separate is-a from has-a. Identify the object that receives the method call, then locate that object's method implementation.", "questions": [{"id": "m19-1", "number": 1, "text": "Basing a subclass on a parent class is called:", "options": ["Inheritance", "Encapsulation", "Concatenation", "Mutation"], "answer": 0, "why": "Inheritance defines an is-a relationship and allows shared behavior."}, {"id": "m19-2", "number": 2, "text": "Hiding internal details behind a controlled interface is called:", "options": ["Encapsulation", "Iteration", "Formatting", "Parsing"], "answer": 0, "why": "Encapsulation lets callers use an interface without manipulating every internal detail."}, {"id": "m19-3", "number": 3, "text": "A subclass supplies its own version of a parent method. This is:", "options": ["Overriding", "Concatenation", "CSS inheritance", "Hoisting"], "answer": 0, "why": "An override replaces inherited behavior for that subclass."}, {"id": "m19-4", "number": 4, "text": "A Car has an Engine. Which relationship best describes this?", "options": ["Composition or association", "An is-a inheritance relationship", "Strict equality", "A global variable"], "answer": 0, "why": "An engine is a component of the car, not its parent type."}, {"id": "m19-5", "number": 5, "text": "A SalariedEmployee is an Employee. Which relationship fits?", "options": ["Inheritance", "A queue", "A hidden input", "Parsing"], "answer": 0, "why": "The specialized employee is a subtype of the broader employee."}, {"id": "m19-6", "number": 6, "text": "In a derived constructor, what must happen before accessing this?", "options": ["Call super()", "Call print()", "Declare a global variable", "Call every child method"], "answer": 0, "why": "super initializes the derived instance via the parent constructor."}, {"id": "m19-7", "number": 7, "text": "How can a child method call the parent version of describe()?", "options": ["super.describe()", "this.parent.describe() in every class", "parent()", "extends.describe()"], "answer": 0, "why": "super provides access to inherited method behavior."}, {"id": "m19-8", "number": 8, "text": "Which field form is private to its declaring JavaScript class?", "options": ["#balance", "protected balance", "public balance", "static balance automatically"], "answer": 0, "why": "JavaScript #private fields are distinct from public properties and are not directly accessible by subclasses."}, {"id": "m19-9", "number": 9, "text": "JavaScript has a native protected field keyword with the same behavior as languages such as Java.", "options": ["True", "False"], "answer": 1, "why": "Protected access can be discussed conceptually, but that keyword is not a native JavaScript class field modifier."}, {"id": "m19-10", "number": 10, "text": "Calling describe() on several different subclasses can run different implementations. This illustrates:", "options": ["Polymorphism", "SQL grouping", "A syntax error", "String escaping"], "answer": 0, "why": "A shared method interface can dispatch to different object behaviors."}], "source": "Assessment-based practice", "written": [{"id": "19-1", "number": 1, "text": "Choose inheritance or composition for each: an HourlyEmployee is an Employee; a Customer has an Address."}, {"id": "19-2", "number": 2, "text": "Explain encapsulation using a balance that may be changed only through a deposit method."}, {"id": "19-3", "number": 3, "text": "A subclass replaces a parent's describe() method with its own version. What is this called, and how does it illustrate polymorphism?"}, {"id": "19-4", "number": 4, "text": "Can an instance property refer to an object of another class? Give a practical example."}, {"id": "19-5", "number": 5, "text": "Write an attempt at a child constructor receiving firstName and lastName and passing them to a parent constructor."}, {"id": "19-6", "number": 6, "text": "What must happen before this is accessed in a derived constructor? Must super literally be the first source statement if earlier statements do not use this?"}, {"id": "19-7", "number": 7, "text": "If a child overrides a method, how could it still request the parent's version inside its own method?"}, {"id": "19-8", "number": 8, "text": "Contrast a public field, a #private field, a static field, a local method variable, and a global variable by scope."}, {"id": "19-9", "number": 9, "text": "Does JavaScript provide a native protected field keyword? How does a conceptual protected field differ from a public field or #private field?"}, {"id": "19-10", "number": 10, "text": "Trace which method is selected when an array contains both parent-class and subclass instances and each object's describe() is called."}, {"id": "19-11", "number": 11, "text": "What does a for...in loop produce when visiting an object's enumerable properties? How would you access each property's value?"}]}, {"id": 20, "title": "Objects in depth", "hint": "Parameters are local bindings. Decide whether the function changes the shared object or only its local binding.", "questions": [{"id": "m20-1", "number": 1, "text": "Which can an object property contain?", "options": ["Another object", "An array", "A string", "All of these"], "answer": 3, "why": "Properties can refer to values of many types, including nested objects."}, {"id": "m20-2", "number": 2, "text": "An object may contain an array of other objects.", "options": ["True", "False"], "answer": 0, "why": "Arrays of objects are a common way to model related data."}, {"id": "m20-3", "number": 3, "text": "Accessing an object stored in another object’s property always requires super().", "options": ["True", "False"], "answer": 1, "why": "super is related to inheritance, not ordinary nested property access."}, {"id": "m20-4", "number": 4, "text": "What is logged?\n```js\nlet city = \"Provo\";\nchange(city);\nconsole.log(city);\nfunction change(input) { input = \"Orem\"; }\n```", "options": ["Provo", "Orem", "undefined", "An error"], "answer": 0, "why": "Reassigning a local parameter does not reassign the caller’s primitive-valued binding."}, {"id": "m20-5", "number": 5, "text": "What is logged?\n```js\nlet city = \"Provo\";\ncity = change(city);\nconsole.log(city);\nfunction change(input) { input = \"Orem\"; }\n```", "options": ["Provo", "Orem", "undefined", "An error"], "answer": 2, "why": "The function returns undefined, which is assigned to city."}, {"id": "m20-6", "number": 6, "text": "What is logged?\n```js\nlet teams = [\"Owls\", \"Bears\"];\nrename(teams);\nconsole.log(teams[0]);\nfunction rename(input) { input[0] = \"Foxes\"; }\n```", "options": ["Owls", "Foxes", "Bears", "undefined"], "answer": 1, "why": "The parameter refers to the same array, so its mutation is observable by the caller."}, {"id": "m20-7", "number": 7, "text": "What is logged?\n```js\nlet teams = [\"Owls\"];\nrename(teams);\nconsole.log(teams[0]);\nfunction rename(input) { input = [\"Foxes\"]; }\n```", "options": ["Owls", "Foxes", "undefined", "An error"], "answer": 0, "why": "Rebinding the parameter to another array does not replace the caller’s binding."}, {"id": "m20-8", "number": 8, "text": "Which accesses the second course’s instructor name?", "options": ["school.courses[1].instructor.name", "school.courses[2].instructor.name", "school[1].courses.name", "school.courses.instructor[1]"], "answer": 0, "why": "The array index for the second item is 1, followed by nested property access."}], "source": "Assessment-based practice", "written": [{"id": "20-1", "number": 1, "text": "Can a single object's attributes contain a string, an array, and another object? Sketch a course object with these three kinds of values."}, {"id": "20-2", "number": 2, "text": "A Student contains an Address object. Does accessing the address require super()? Explain what super relates to instead."}, {"id": "20-3", "number": 3, "text": "Who supplies the Address object: must Student create one, or could an existing object be passed into Student's constructor?"}, {"id": "20-4", "number": 4, "text": "Suppose `school.courses[1].instructor.name` is an expression. Describe each access step."}, {"id": "20-5", "number": 5, "text": "Trace:\n```js\nlet language = 'Ruby';\nchange(language);\nconsole.log(language);\nfunction change(input) { input = 'Go'; }\n```"}, {"id": "20-6", "number": 6, "text": "Trace the same code if the call becomes `language = change(language);` but the function still has no return statement."}, {"id": "20-7", "number": 7, "text": "Trace:\n```js\nlet teams = ['Falcons', 'Owls'];\nrename(teams);\nconsole.log(teams[0]);\nfunction rename(input) { input[0] = 'Bears'; }\n```"}, {"id": "20-8", "number": 8, "text": "What changes if rename instead executes `input = ['Bears'];`? Explain mutation versus reassignment."}, {"id": "20-9", "number": 9, "text": "If two objects refer to the same Address object, what might both observe when that address's city changes?"}, {"id": "20-10", "number": 10, "text": "How could an object's attribute hold an array of objects? Write an attempt to select the third object and call its method."}]}, {"id": 21, "title": "Node and Express", "hint": "Keep browser storage separate from server-side processing. Session storage is associated with a tab's page session and origin.", "questions": [{"id": "m21-1", "number": 1, "text": "Which storage is designed to persist across browser sessions until removed?", "options": ["localStorage", "sessionStorage only", "A local function variable", "A call stack frame"], "answer": 0, "why": "localStorage persists beyond one tab session, though users or browser policies may remove it."}, {"id": "m21-2", "number": 2, "text": "Closing an unrelated tab necessarily deletes sessionStorage in a tab that remains open.", "options": ["True", "False"], "answer": 1, "why": "sessionStorage is associated with an origin and a particular tab’s page session."}, {"id": "m21-3", "number": 3, "text": "Which correctly stores a theme?", "options": ["localStorage.setItem(\"theme\", \"dark\")", "localStorage.setItem(\"dark\")", "localStorage(\"theme\", \"dark\")", "localStorage.getItem(\"theme\", \"dark\")"], "answer": 0, "why": "setItem takes a key and a value."}, {"id": "m21-4", "number": 4, "text": "The storage keys theme and Theme are distinct.", "options": ["True", "False"], "answer": 0, "why": "Storage keys are case-sensitive strings."}, {"id": "m21-5", "number": 5, "text": "localStorage can contain only one key-value pair.", "options": ["True", "False"], "answer": 1, "why": "It can contain multiple pairs, subject to browser storage limits."}, {"id": "m21-6", "number": 6, "text": "How can an object commonly be stored in localStorage?", "options": ["Serialize with JSON.stringify", "Pass a SQL connection", "Use a protected field", "Rename it with an s prefix"], "answer": 0, "why": "Browser storage stores strings; JSON.stringify encodes an object into a string."}, {"id": "m21-7", "number": 7, "text": "Which allows JavaScript to run on the server?", "options": ["Node.js", "HTML comments", "CSS", "A datalist"], "answer": 0, "why": "Node is a JavaScript runtime used for server-side applications and other programs."}, {"id": "m21-8", "number": 8, "text": "What is npm primarily used for?", "options": ["Managing JavaScript packages", "Automatically hosting every website", "Rendering HTML in the browser", "Creating PostgreSQL tables"], "answer": 0, "why": "npm is a package manager, commonly included with Node installations."}, {"id": "m21-9", "number": 9, "text": "What does Express primarily simplify?", "options": ["Server-side request handling and routing", "Only paragraph styling", "Password masking in inputs", "A browser’s print dialog"], "answer": 0, "why": "Express provides reusable functionality for Node web applications."}, {"id": "m21-10", "number": 10, "text": "Which file is commonly created by npm init?", "options": ["package.json", "index.html", "database.sql", "styles.css"], "answer": 0, "why": "package.json records project metadata, scripts, and package information."}], "source": "Assessment-based practice", "written": [{"id": "21-1", "number": 1, "text": "Contrast localStorage with sessionStorage in terms of persistence across reloads, tab closure, and later visits."}, {"id": "21-2", "number": 2, "text": "One tab has sessionStorage data and another unrelated tab is closed. Does closing that unrelated tab necessarily delete the first tab's data?"}, {"id": "21-3", "number": 3, "text": "Write attempts to store and retrieve a theme under a named localStorage key. What two arguments does setItem require?"}, {"id": "21-4", "number": 4, "text": "Are 'theme' and 'Theme' the same storage key? Can storage contain several keys at once?"}, {"id": "21-5", "number": 5, "text": "What data type does browser storage directly store? How could an object be encoded and restored?"}, {"id": "21-6", "number": 6, "text": "Describe the server's work between receiving an HTTP request and sending a response."}, {"id": "21-7", "number": 7, "text": "What makes Node.js useful to someone who already knows browser JavaScript? Is Node a browser?"}, {"id": "21-8", "number": 8, "text": "Distinguish Node.js, npm, and Express by their responsibilities. Is npm primarily a website deployment service?"}, {"id": "21-9", "number": 9, "text": "What is package.json used for, and how can npm init help create it?"}, {"id": "21-10", "number": 10, "text": "Does Express eliminate the need to write all application logic? Explain what it simplifies."}]}, {"id": 22, "title": "PostgreSQL", "hint": "Separate the database server, its interface tools, SQL commands, and psql shortcuts. Precision counts all digits; scale counts fractional digits.", "questions": [{"id": "m22-1", "number": 1, "text": "Which holds one field’s values across the rows of a table?", "options": ["Column", "Database", "Complete record", "Server"], "answer": 0, "why": "A column describes one attribute, such as student_name."}, {"id": "m22-2", "number": 2, "text": "Which describes a relational database?", "options": ["Data organized in related tables queried with SQL", "A system that cannot use SQL", "Only a browser cache", "Only a proprietary file format"], "answer": 0, "why": "Relational systems model data in tables with relationships and constraints."}, {"id": "m22-3", "number": 3, "text": "In the course’s categories, CREATE TABLE belongs to:", "options": ["DDL", "DCL", "TCL", "DML"], "answer": 0, "why": "Data Definition Language defines schema structures."}, {"id": "m22-4", "number": 4, "text": "GRANT SELECT ON students TO reader is an example of:", "options": ["DCL", "DDL", "TCL", "CSS"], "answer": 0, "why": "Data Control Language manages permissions."}, {"id": "m22-5", "number": 5, "text": "COMMIT belongs to which category?", "options": ["TCL", "DDL", "DCL", "HTML"], "answer": 0, "why": "Transaction Control Language controls transaction boundaries."}, {"id": "m22-6", "number": 6, "text": "Under the course’s classification, SELECT is grouped with:", "options": ["DML", "DCL", "TCL", "CSS"], "answer": 0, "why": "The assessment groups SELECT with DML; other classifications distinguish DQL."}, {"id": "m22-7", "number": 7, "text": "pgAdmin is a graphical tool for working with PostgreSQL databases.", "options": ["True", "False"], "answer": 0, "why": "It is an interface tool; PostgreSQL is the database system itself."}, {"id": "m22-8", "number": 8, "text": "Which psql shortcut connects to a database named campus?", "options": ["\\c campus", "set connection = campus", "connect() campus", "\\table campus"], "answer": 0, "why": "The psql meta-command \\c, also \\connect, changes the connection."}, {"id": "m22-9", "number": 9, "text": "Which psql shortcut lists databases?", "options": ["\\l", "\\d only", "\\display", "list()"], "answer": 0, "why": "\\l, also \\list, lists databases."}, {"id": "m22-10", "number": 10, "text": "PostgreSQL normally folds unquoted identifiers to:", "options": ["Lowercase", "Uppercase", "Title case", "Random case"], "answer": 0, "why": "Quoted identifiers preserve exact case; unquoted identifiers fold to lowercase."}, {"id": "m22-11", "number": 11, "text": "Which value fits numeric(4,2) without overflow?", "options": ["82.45", "182.45", "1282.45", "An arbitrary-length integer"], "answer": 0, "why": "Four total digits with two decimal places permit two digits before the decimal."}, {"id": "m22-12", "number": 12, "text": "Which type is a suitable choice for a calendar date?", "options": ["date", "boolean", "integer only", "varchar always"], "answer": 0, "why": "The date type directly represents a calendar date."}, {"id": "m22-13", "number": 13, "text": "Which type is intended for a true/false field?", "options": ["boolean", "integer only", "numeric(3,2)", "date"], "answer": 0, "why": "PostgreSQL supports a boolean type."}], "source": "Assessment-based practice", "written": [{"id": "22-1", "number": 1, "text": "A database contains a Students table with many rows and columns. Explain database, table, record, and column using this example."}, {"id": "22-2", "number": 2, "text": "What makes a database relational? Does that mean it cannot use SQL?"}, {"id": "22-3", "number": 3, "text": "Match these commands to your course's DDL, DML, DCL, and TCL categories: CREATE TABLE, SELECT, GRANT, COMMIT. Explain each command's role. Some references classify SELECT separately as DQL."}, {"id": "22-4", "number": 4, "text": "What does pgAdmin provide? How does a graphical tool differ from the PostgreSQL database server?"}, {"id": "22-5", "number": 5, "text": "In psql, write an attempt to connect to a database named campus and an attempt to list databases. These are psql commands rather than SQL statements."}, {"id": "22-6", "number": 6, "text": "Compare an unquoted identifier StudentName with the quoted identifier \"StudentName\". What effect does PostgreSQL's case folding have?"}, {"id": "22-7", "number": 7, "text": "Choose suitable types for a whole-number quantity, a name, a calendar date, a yes/no flag, and an exact decimal price."}, {"id": "22-8", "number": 8, "text": "Explain precision and scale in numeric(5,2). Would 123.45 fit? Would 1234.56 fit? Show how you decide rather than guessing."}, {"id": "22-9", "number": 9, "text": "Compare numeric(3,2) and numeric(6,2). How many digits can each hold to the left of the decimal point?"}, {"id": "22-10", "number": 10, "text": "PostgreSQL accepts several textual representations of boolean values. Why might you still prefer a clear true/false representation in queries and code?"}]}, {"id": 23, "title": "Mixed practice", "hint": "Work one layer at a time: event → input → conversion → logic → data structure → display. For object questions, draw references.", "questions": [], "source": "Application practice", "written": [{"id": "23-1", "number": 1, "text": "A text input contains '4'. A function adds it to a numeric total of 10 and gets an unexpected result. Trace the values, locate the conversion point, and propose your own fix."}, {"id": "23-2", "number": 2, "text": "A form creates Student objects and stores them in an array. Sketch the path from a submit event to reading .value, creating the object, adding it, and rendering the list."}, {"id": "23-3", "number": 3, "text": "A selected student's index is 2 in an array of length 5. Which array method could remove that one student without removing the last student? Write an attempt and predict the new length."}, {"id": "23-4", "number": 4, "text": "A BeginnerClient subclass has a different recommendation from AdvancedClient. Explain how inheritance, overriding, and polymorphism could work together when rendering an array of clients."}, {"id": "23-5", "number": 5, "text": "A loop generates a day-by-day workout summary. It prints undefined before the first line and repeats forever. Identify two separate categories of things to inspect before rewriting it."}, {"id": "23-6", "number": 6, "text": "A summary method produces a long decimal for calories. Where would you investigate calculation versus display formatting? Would changing a shared total to a string have consequences?"}, {"id": "23-7", "number": 7, "text": "A client owns an array of Workout objects. Write an attempt to access the second workout's minutes, then describe what would happen if there is only one workout."}, {"id": "23-8", "number": 8, "text": "A page successfully saves a profile in localStorage. Does that mean another device can retrieve it from your PostgreSQL database? Explain the separate storage locations."}, {"id": "23-9", "number": 9, "text": "A student's name is updated through a second reference to the same object. Trace what the original reference observes. Compare with reassigning the second reference to a new object."}, {"id": "23-10", "number": 10, "text": "You have no AI during the exam and a button does nothing. Describe a repeatable debugging routine using the console, a breakpoint, and inspection of the DOM selector and handler."}]}];